// Check that uvm class names can be used unqualified at global scope after
// 'using namespace uvm', i.e. no conflicting global declarations exist.

#include <iostream>
#include <string>
#include <uvm>

using namespace uvm;

// global-scope declarations using unqualified names
uvm_object* p = nullptr;
uvm_printer* q = nullptr;
uvm_event_callback* r = nullptr;

class my_callback : public uvm_event_callback
{
public:
  my_callback( const std::string& name = "my_callback" )
  : uvm_event_callback(name) {}

  virtual bool pre_trigger( const uvm_event* e, const uvm_object* data = nullptr ) const
  {
    std::cout << "pre_trigger called" << std::endl;
    return false;
  }

  virtual void post_trigger( const uvm_event* e, const uvm_object* data = nullptr ) const
  {
    std::cout << "post_trigger called" << std::endl;
  }
};

int sc_main( int argc, char** argv )
{
  my_callback cb;
  uvm::uvm_event_callback* ucb = &cb;
  r = ucb;

  uvm_event ev("ev");
  p = &ev;

  ev.add_callback(ucb);
  ev.trigger();
  ev.delete_callback(ucb);
  ev.reset();
  ev.trigger();

  std::cout << "done" << std::endl;
  return 0;
}
EOF
